css:
.panel {
  display: grid;
  gap: 20px;
  justify-items: start;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.avatars {
  display: flex;
  gap: 16px;
}

.avatar {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background-color: #fdba74;
  font-weight: 600;
}

.selected {
  box-shadow: 0 0 0 3px #ffffff, 0 0 0 6px #f97316;
}

.field {
  width: 260px;
  padding: 10px 12px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  box-shadow: inset 0 2px 4px rgb(0 0 0 / 0.12);
  font: inherit;
}
